const carried = planPrev.filter(function (p) { return p.st === 'not_done' || p.st === 'no_answer'; }).map(function (p) { return { text: p.text, origin_week: p.origin_week, carry_count: p.carry_count + 1 }; });
// Пункти плану ділимо по рядках, по «;» і по маркерах «1)» / «2)» (ПМ часто пише в один рядок)
const newTexts = String(plansNextWeek || '').split(/\n|;|(?<=\S)\s+(?=\d{1,2}\)\s)/).map(function (l) { const m = l.trim().match(/^\d+[.)]\s+(.+)$/); return (m ? m[1] : l).trim(); }).filter(Boolean)
  .filter(function (t) { return !carried.some(function (cp) { return String(cp.text).toLowerCase() === t.toLowerCase(); }); });
const planNextItems = carried.concat(newTexts.map(function (t) { return { text: t, origin_week: nextWeekStart, carry_count: 0 }; }));

function clampInt1to10(v){
  if (v === null || v === undefined || v === '') return null;
  var n = typeof v === 'number' ? v : parseFloat(String(v).replace(',', '.'));
  if (isNaN(n)) return null;
  n = Math.round(n);
  if (n < 1) n = 1;
  if (n > 10) n = 10;
  return n;
}
function cleanStageReadiness(obj){
  if (!obj || typeof obj !== 'object') return null;
  var allowedStages = ['МБР','ЕП','П','Р'];
  var out = {};
  var any = false;
  allowedStages.forEach(function(s){
    var v = obj[s];
    if (v === null || v === undefined || v === '') return;
    var n = typeof v === 'number' ? v : parseFloat(String(v).replace(',', '.').replace('%',''));
    if (isNaN(n)) return;
    if (n < 0) n = 0;
    if (n > 100) n = 100;
    out[s] = n;
    any = true;
  });
  return any ? out : null;
}
function cleanStageHours(obj){
  if (!obj || typeof obj !== 'object') return null;
  var allowedStages = ['МБР','ЕП','П','Р'];
  var out = {};
  var any = false;
  allowedStages.forEach(function(s){
    var v = obj[s];
    if (v === null || v === undefined || v === '') return;
    var n = typeof v === 'number' ? v : parseFloat(String(v).replace(',', '.'));
    if (isNaN(n) || n < 0) return;
    out[s] = n;
    any = true;
  });
  return any ? out : null;
}

let stageReadiness = cleanStageReadiness(out.stage_readiness);
// Стадії, яких немає в договорі (ETC_план 0 у Кошторисі), не питаються і не вимагаються (рішення власника 13.10.2026): готовність 100%, ETC 0
let planByStage0 = {};
try { planByStage0 = ($('WR: Fetch Project Metrics Static').first().json || {}).etc_plan_by_stage || {}; if (typeof planByStage0 === 'string') planByStage0 = JSON.parse(planByStage0); } catch (e) { planByStage0 = {}; }
const hasPlan0 = Object.keys(planByStage0).length > 0;
const unsShow = unsupported.filter(function (u) { return !(u.s && hasPlan0 && !(Number(planByStage0[u.s]) > 0)); }).map(function (u) { return u.t; });
if (unsShow.length) pre.push('⚠️ <b>Не підтверджено вашим текстом — прибрано з звіту</b>\n' + unsShow.map(function (u) { return '• ' + u; }).join('\n') + '\n\nНапишіть ці значення своїми словами (число або дату) — інакше вони не потраплять у звіт.');
['МБР','ЕП','П','Р'].forEach(function(s){ if (hasPlan0 && !(Number(planByStage0[s]) > 0)) { if (!stageReadiness) stageReadiness = {}; stageReadiness[s] = 100; } });
let etcForecastStage = cleanStageHours(out.etc_forecast_hours_stage);
// Усі нулі від LLM (і готовність, і ETC) = ПМ ще нічого не дав: це не дані
if (stageReadiness && etcForecastStage && Object.keys(stageReadiness).every(function (k) { return stageReadiness[k] === 0; }) && Object.keys(etcForecastStage).every(function (k) { return etcForecastStage[k] === 0; })) { stageReadiness = null; etcForecastStage = null; }
const STG4 = ['МБР','ЕП','П','Р'];
// Стадія з готовністю 100% завершена: ETC_прогноз = 0 автоматично, ETC і дата у ПМа не питаються (рішення власника 10.10.2026)
const doneSt = STG4.filter(function(s){ return stageReadiness && stageReadiness[s] !== undefined && stageReadiness[s] >= 100; });
doneSt.forEach(function(s){ if (!etcForecastStage) etcForecastStage = {}; if (etcForecastStage[s] === undefined) etcForecastStage[s] = 0; });
const noAns = (Array.isArray(out.no_answer) ? out.no_answer.map(function(x){ return String(x).trim(); }) : []).filter(function(k){ const m = /^(ETC|дата):(МБР|ЕП|П|Р)$/.exec(k); return !(m && doneSt.indexOf(m[2]) >= 0); });
const na = function(k){ return noAns.indexOf(k) >= 0; };
// Завершена стадія (100%) — LLM не питає про її дедлайн (правило власника 10.10.2026); прибираємо такі питання з ask
if (doneSt.length) { ask = ask.split(/(?<=\?)\s*/).filter(function (part) { return !doneSt.some(function (s) { return part.indexOf('дедлайн стадії ' + s) >= 0; }); }).join(' ').trim(); }
// Ймовірність Акту — АВТО за Кошторисом (перша стадія з непідписаним Актом), не від LLM
let actAuto = null;
try { actAuto = $('WR: Build WR Prompt').first().json.act_probability_auto; } catch (e) { actAuto = null; }
const actProbability = (actAuto !== null && actAuto !== undefined) ? clampInt1to10(actAuto) : clampInt1to10(out.act_probability);
const docProbability = clampInt1to10(out.doc_probability);
const problemsText = out.problems_text || null;
const helpText = out.help_text || null;
const pmCommentText = out.pm_comment_text || null;

// Блокер: {types:[...], since, need}; {types:[]} — немає; null — ПМ ще не відповів
const BLOCK_TYPES = ['люди','гроші','замовник','інше'];
let blocker = null;
if (Array.isArray(out.blocker_types)) {
  const types = out.blocker_types.map(function (t) { return String(t).trim().toLowerCase(); }).filter(function (t) { return BLOCK_TYPES.indexOf(t) >= 0; });
  const since = /^[0-9]{4}-[0-9]{2}-[0-9]{2}$/.test(String(out.blocker_since || '')) ? String(out.blocker_since) : null;
  blocker = types.length ? { types: types, since: since, need: out.blocker_need ? String(out.blocker_need) : null } : { types: [] };
}

// БРИФ: фінал приймається тільки з обов'язковими відповідями (код, не рішення LLM)
const missing = [];
const todayKyiv = new Date().toLocaleDateString('sv-SE', { timeZone: 'Europe/Kyiv' });
if (wantFinal) {
  const STG = ['МБР','ЕП','П','Р'];
  const dl = (out.deadline_forecast_stage && typeof out.deadline_forecast_stage === 'object') ? out.deadline_forecast_stage : {};
  STG.forEach(function (s) {
    const m = [];
    if ((!stageReadiness || stageReadiness[s] === undefined) && !na('готовність:' + s)) m.push('готовність %');
    if ((!etcForecastStage || etcForecastStage[s] === undefined) && !na('ETC:' + s)) m.push('скільки годин ще потрібно');
    if (doneSt.indexOf(s) < 0 && (!dl[s] || !/^[0-9]{4}-[0-9]{2}-[0-9]{2}$/.test(String(dl[s]))) && !na('дата:' + s)) m.push('дата завершення');
    // Рішення власника 25.10.2026: прогнозна дата незавершеної стадії не може бути в минулому — нова дата або «відповіді нема»
    else if (doneSt.indexOf(s) < 0 && /^[0-9]{4}-[0-9]{2}-[0-9]{2}$/.test(String(dl[s] || '')) && String(dl[s]) < todayKyiv) {
      if (na('дата:' + s)) { delete dl[s]; } else { m.push('дата завершення (прогнозна дата ' + String(dl[s]).split('-').reverse().join('.') + ' вже минула — вкажіть нову дату або «відповіді нема»)'); }
    }
    if (m.length) missing.push(s + ': ' + m.join(', '));
  });
  if (docProbability === null && !na('документація')) missing.push('ймовірність видачі документації (1–10)');
  if (!planNextItems.length && !na('план')) missing.push('план на наступний тиждень (нових пунктів немає й переносити нічого — додайте пункти або напишіть «відповіді нема»)');
  planPending.forEach(function (p) { missing.push('статус пункту плану №' + p.n + ' «' + p.text + '»: виконано / не виконано / відповіді нема'); });
  if (!blocker && !na('блокер')) missing.push('чи є блокер (що зупиняє роботу; якщо нічого — «немає»)');
  else if (blocker && blocker.types.length && !blocker.since) missing.push('блокер: з якої дати проєкт стоїть');
  if (missing.length) {
    pre.push('⚠️ <b>Фінал не прийнято</b>' + String.fromCharCode(10) + 'Бракує відповідей з брифу:' + String.fromCharCode(10) + String.fromCharCode(10) + missing.map(function (x) { return '• ' + x; }).join(String.fromCharCode(10)) + String.fromCharCode(10) + String.fromCharCode(10) + 'Додайте їх і натисніть «Фінал» ще раз.');
  }
}

// «ВІДПОВІДІ НЕМА»: явний стан для елементів брифу (рядок у проблемах + у звіті; значення в БД не вигадуються)
const NA_LABELS = { 'документація': 'ймовірність видачі документації', 'план': 'план на наступний тиждень', 'блокер': 'чи є блокер' };
const naLines = noAns.map(function (k) {
  const m = /^(готовність|ETC|дата):(МБР|ЕП|П|Р)$/.exec(k);
  if (m) return (m[1] === 'готовність' ? 'готовність' : m[1] === 'ETC' ? 'ETC_прогноз' : 'дата завершення') + ' ' + m[2];
  return NA_LABELS[k] || null;
}).filter(Boolean);
let problemsOut = problemsText;
if (naLines.length) {
  const naText = '❓ Відповіді нема (ПМ): ' + naLines.join('; ');
  problemsOut = problemsText ? (problemsText + String.fromCharCode(10) + naText) : naText;
}

// ПЕРЕВІРКА ГОТОВНОСТІ (код, не ШІ): оцінка ПМ vs за годинами = витрачено / (витрачено + ETC_прогноз)
const pmStatic = $('WR: Fetch Project Metrics Static').first().json || {};
const GAP_PP = (pmStatic.readiness_gap_pp !== null && pmStatic.readiness_gap_pp !== undefined && !isNaN(Number(pmStatic.readiness_gap_pp))) ? Number(pmStatic.readiness_gap_pp) : 20;
let sdLive = pmStatic.stage_data || {};
if (typeof sdLive === 'string') { try { sdLive = JSON.parse(sdLive); } catch (e) { sdLive = {}; } }
const NLc = String.fromCharCode(10);
const gaps = {};
if (stageReadiness && etcForecastStage) {
  ['МБР','ЕП','П','Р'].forEach(function (s) {
    const pmR = stageReadiness[s], etc = etcForecastStage[s];
    if (pmR === undefined || etc === undefined || na('готовність:' + s) || na('ETC:' + s) || (pmR === 0 && etc === 0)) return;
    const act = Number((sdLive[s] || {}).actual_hours_live) || 0;
    if (act + etc <= 0) return;
    const byHours = Math.round(act / (act + etc) * 100);
    if (Math.abs(pmR - byHours) >= GAP_PP) gaps[s] = { pm: pmR, hours: byHours, act: Math.round(act * 10) / 10, etc: etc };
  });
}
const gapStages = Object.keys(gaps);
const gapConfirmed = out.readiness_gap_confirmed === true || /підтверджу\S*\s+розбіжн|розбіжн\S*\s+підтвердж/i.test(String(hl.payload || ''));
const gapNote = out.readiness_gap_note ? String(out.readiness_gap_note) : null;
let readinessGap = null;
let gapOpen = false;
let gapPostBlock = null;
if (gapStages.length) {
  const gapLines = gapStages.map(function (s) { const g = gaps[s]; return '<b>Стадія ' + s + '</b>' + NLc + '• Оцінка ПМ: ' + g.pm + '%' + NLc + '• За годинами: ' + g.hours + '%' + NLc + '• Витрачено: ' + g.act + ' год' + NLc + '• ETC_прогноз: ' + g.etc + ' год'; }).join(NLc + NLc);
  if (!gapConfirmed) {
    const gapAsk = '⚖️ <b>Готовність не збігається з годинами</b>' + NLc + NLc + gapLines + NLc + NLc + '🎯 <b>Що зробити:</b>' + NLc + '• Перевірте оцінку готовності або ETC_прогноз і надішліть виправлені цифри' + NLc + '• Якщо все правильно — напишіть «підтверджую розбіжність» і коротко чому: розбіжність буде зафіксована у звіті';
    gapOpen = true;
    pre.push((wantFinal && !missing.length ? '⚠️ <b>Фінал не прийнято</b>' + NLc + NLc : '') + gapAsk);
  } else {
    gapStages.forEach(function (s) { if (gapNote) gaps[s].note = gapNote; });
    readinessGap = gaps;
    gapPostBlock = ('<b>⚖️ Розбіжність готовності (підтверджено ПМ)</b>' + NLc + NLc + gapLines + (gapNote ? NLc + NLc + 'Пояснення ПМ: ' + String(gapNote).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;') : ''));
  }
}

// РІШЕННЯ «ФІНАЛ»: приймається лише командою ПМа + підтвердженими відповідями (код), не відповіддю LLM
const accepted = wantFinal && !missing.length && !gapOpen;
tag = accepted ? 'FINAL_REPORT' : 'DRAFT';
if (accepted) ask = '';   // прийнятий фінал — питань до ПМа нема
if (accepted && gapPostBlock) post.push(gapPostBlock);

// ПІДСУМКОВІ РЯДКИ — рахує код, не LLM (прогноз лише від ПМа; без даних — «—», не 0 і не план)
const etcMissing = STG4.filter(function (s) { return !(etcForecastStage && etcForecastStage[s] !== undefined); });
const etcTotalFc = etcMissing.length ? null : STG4.reduce(function (a, s) { return a + etcForecastStage[s]; }, 0);
if (etcTotalFc === null) {
  post.push('🔴 <b>Прогноз проєкту ' + (tag === 'FINAL_REPORT' ? '' : 'ще ') + 'не розраховано</b>' + NLc + '• ПМ не дав ETC по: ' + etcMissing.join(', ') + NLc + '• Прогноз — лише від ПМа, план замість нього не підставляється');
}

// Дата завершення завершеної стадії (100%) не зберігається: її ПМ не дає, LLM може її вигадати (знахідка 25.10.2026)
let dlOut = (out.deadline_forecast_stage && typeof out.deadline_forecast_stage === 'object') ? Object.assign({}, out.deadline_forecast_stage) : null;
if (dlOut) { doneSt.forEach(function (s) { delete dlOut[s]; }); }

return [{ json: {
  tag: tag,
  ask: ask,
  pre_blocks: pre,
  post_blocks: post,
  etc_total_forecast: etcTotalFc,
  etc_missing: etcMissing,
  no_answer: noAns,
  project_id: hl.project_id,
  item_statuses: itemStatusesOut,
  plan_prev: planPrev,
  plan_next_items: planNextItems,
  plans_next_week: plansNextWeek,
  stage_readiness: stageReadiness,
  etc_forecast_stage: etcForecastStage,
  deadline_forecast_stage: dlOut,
  act_probability: actProbability,
  doc_probability: docProbability,
  problems_text: problemsOut,
  help_text: helpText,
  pm_comment_text: pmCommentText,
  blocker: blocker,
  readiness_gap: readinessGap
} }];

// План наступного тижня (перенесене + нове) уже складено в WR: Parse Agent Output (plan_next_items) — тут лише передача далі
const parsed = $input.first().json;
return [{ json: { project_id: parsed.project_id, combined_items: parsed.plan_next_items || [] } }];

const item = $input.first();
const projectId = item.json.project_id;
const items = item.json.combined_items || [];
const nextWeekStart = $now.startOf('week').plus({ weeks: 1 }).toFormat('yyyy-MM-dd');
if (!items.length) return [];
return items.map(function(it, idx){
  return { json: { project_id: projectId, week_start: nextWeekStart, item_number: idx + 1, item_text: it.text, origin_week: it.origin_week || nextWeekStart, carry_count: Number(it.carry_count) || 0 } };
});

const item = $input.first();
let raw = item.json.output ?? item.json.text ?? '';
if (typeof raw === 'string') raw = raw.trim().replace(/^```(?:json)?\s*/i,'').replace(/```\s*$/,'').trim();
let out;
try { out = typeof raw === 'string' ? JSON.parse(raw) : raw; } catch(e) { out = { tag:'DRAFT', message: String(raw) }; }
const hl = $('WR: Hard Logic Engine').first().json;
let message = out.message || '';
const rawTag = out.tag || 'DRAFT';
let tag = (hl.execution_mode === 'generate_import_final' && rawTag === 'FINAL_REPORT') ? 'FINAL_REPORT' : 'DRAFT';
function esc(s){ return String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;'); }

function cleanTimeRows(rows) {
  if (!Array.isArray(rows)) return [];
  const allowedStages = ['МБР','ЕП','П','Р'];
  return rows.filter(function(r){ return r && r.date && allowedStages.includes(r.stage) && r.executor && r.hours != null; });
}
function cleanMoneyRows(rows) {
  if (!Array.isArray(rows)) return [];
  const allowedTypes = ['оплата_субпідряднику','надходження_від_замовника','акт_підписаний'];
  return rows.filter(function(r){ return r && r.date && r.counterparty && r.amount != null && allowedTypes.includes(r.type); });
}

// БРИФ: неповні рядки не відкидаються мовчки — фінал блокується з переліком
if (tag === 'FINAL_REPORT') {
  const NL = String.fromCharCode(10);
  const ST = ['МБР','ЕП','П','Р'];
  const TY = ['оплата_субпідряднику','надходження_від_замовника','акт_підписаний'];
  const problems = [];
  const badNum = function (v) { if (v === null || v === undefined || v === '') return true; const n = Number(String(v).replace(/\s/g, '').replace(',', '.')); return isNaN(n) || n <= 0; };
  (Array.isArray(out.time_rows) ? out.time_rows : []).forEach(function (r, i) {
    const m = [];
    if (!r || !r.date) m.push('дата');
    if (!r || ST.indexOf(r.stage) < 0) m.push('стадія (МБР/ЕП/П/Р)');
    if (!r || !r.executor) m.push('виконавець');
    if (!r || badNum(r.hours)) m.push('кількість годин');
    if (m.length) problems.push('⏱ Години, рядок ' + (i + 1) + ' (' + [r && r.date, r && r.executor, r && r.hours].filter(Boolean).join(', ') + '): бракує ' + m.join(', '));
  });
  (Array.isArray(out.money_rows) ? out.money_rows : []).forEach(function (r, i) {
    const m = [];
    if (!r || !r.date) m.push('дата');
    if (!r || TY.indexOf(r.type) < 0) m.push('тип (оплата субпідряднику / надходження від замовника / акт підписаний)');
    if (!r || !r.counterparty) m.push('контрагент');
    if (!r || badNum(r.amount)) m.push('сума');
    if (m.length) problems.push('💵 Гроші, рядок ' + (i + 1) + ' (' + [r && r.date, r && r.counterparty, r && r.amount].filter(Boolean).join(', ') + '): бракує ' + m.join(', '));
  });
  const total = (Array.isArray(out.time_rows) ? out.time_rows.length : 0) + (Array.isArray(out.money_rows) ? out.money_rows.length : 0);
  if (total === 0) problems.push('немає жодного рядка годин чи грошей');
  if (problems.length) {
    tag = 'DRAFT';
    message = '⚠️ <b>Фінал не прийнято</b>' + NL + 'Неповні дані:' + NL + NL + problems.map(function (x) { return '• ' + esc(x); }).join(NL) + NL + NL + 'Доповніть і натисніть «Фінал» ще раз.' + NL + '🚫 Нічого не записано.';
  }
}

return [{ json: {
  tag: tag,
  message: message,
  project_id: hl.project_id,
  time_rows: cleanTimeRows(out.time_rows),
  money_rows: cleanMoneyRows(out.money_rows)
} }];

