const item = $input.first().json;
const rows = item.time_rows || [];
return rows.map(function(r){
  return { json: {
    ProjectID: item.project_id,
    Дата: r.date,
    Стадія: r.stage,
    Виконавець: r.executor,
    'Завдання / розділ': r.task_section || '',
    Години: r.hours,
    Статус: 'confirmed'
  } };
});

const item = $input.first().json;
const rows = item.money_rows || [];
return rows.map(function(r){
  return { json: {
    ProjectID: item.project_id,
    Дата: r.date,
    Стадія: r.stage || '',
    Контрагент: r.counterparty,
    Сума: r.amount,
    Тип: r.type,
    Статус: 'confirmed'
  } };
});

const hl = $('WR: Hard Logic Engine').first().json;
const today = new Date().toISOString().slice(0,10);

const systemPrompt = 'Ти — асистент, що обробляє транскрипти нарад для проєкту ' + hl.project_id + ' і витягує з них рішення/дії (action items).\n' +
