let tag = (hl.execution_mode === 'generate_meeting_final' && rawTag === 'FINAL_REPORT') ? 'FINAL_REPORT' : 'DRAFT';

// БРИФ: кожне рішення — з відповідальним і дедлайном; дата й учасники зустрічі
let briefMsg = null;
if (tag === 'FINAL_REPORT') {
  const NL = String.fromCharCode(10);
  const items = Array.isArray(out.items) ? out.items : [];
  const problems = [];
  if (!out.participants) problems.push('учасники зустрічі');
  if (!items.length) problems.push('жодного рішення');
  items.forEach(function (it, i) {
    const m = [];
