  var vp = toNum(r.visits_plan) || 0, vd = toNum(r.visits_done) || 0;
  var rentP = toNum(r.profitability_plan_pct), rentF = toNum(r.profitability_forecast_pct), cpiA = toNum(r.cpi_classic_evm);
  var drop = (rentP !== null && rentF !== null) ? (rentP - rentF) : null;
  var st = 'green', sig = [];
  if (rentF !== null && rentF < 0) { st = 'red'; sig.push('Рентабельність прогноз ' + fmtPct(rentF) + ' — договір у збитку'); }
  else if (drop !== null && drop >= DROP_RED) { st = 'red'; sig.push('Рентабельність прогноз на ' + (Math.round(drop * 10) / 10) + ' п.п. нижче плану'); }
  else if (drop !== null && drop >= DROP) { st = 'yellow'; sig.push('Рентабельність прогноз на ' + (Math.round(drop * 10) / 10) + ' п.п. нижче плану'); }
  if (cpiA !== null && cpiA < CPI_RED) { st = 'red'; sig.push('CPI ' + fmtRatio(cpiA) + ' — перевитрата на виїздах'); }
  else if (cpiA !== null && cpiA < CPI_YELLOW) { st = worst(st, 'yellow'); sig.push('CPI ' + fmtRatio(cpiA) + ' — на межі'); }
  if (C > 0 && S - Rc > C * UNP_R) { st = 'red'; sig.push('Акти не оплачено: ' + fmtUAH(S - Rc)); }
  else if (C > 0 && S - Rc > C * UNP_Y) { st = worst(st, 'yellow'); sig.push('Акти не оплачено: ' + fmtUAH(S - Rc)); }
  return { id: String(r.project_id), parent: r.parent_project_id || null, status: st, signals: sig, visitsFmt: vd + ' з ' + vp, priceFmt: fmtUAH(toNum(r.visit_price)), contractFmt: fmtUAH(C), actsFmt: fmtUAH(S), receivedFmt: fmtUAH(Rc), costFmt: fmtUAH(Q), rentPlanFmt: fmtPct(rentP), rentForecastFmt: fmtPct(rentF), cpiFmt: fmtRatio(cpiA) };
});
return [{ json: Object.assign({}, bmd, { an: an }) }];

// Блок «Авторський нагляд» в Owner View: вставляється в готовий HTML (дані — data.an з вузла AN: Attach Block)
const out = $input.first().json;
let html = out.html;
const A = "(attHtml ? '<div class=\"section-title\">Потребують уваги</div>' + attHtml : '');";
const B = "  document.getElementById('app').innerHTML =\n    '<h1>📊 Портфель</h1>' +";
if (html.indexOf(A) < 0 || html.indexOf(B) < 0) { throw new Error('AN: Patch HTML — не знайдено якорі в Build MiniApp HTML (змінилася верстка?)'); }
const AN_BLOCK = "  const anHtml = (DATA.an || []).length ? '<div class=\"section-title\">Авторський нагляд · окремі договори (оплата за виїзд)</div>' + DATA.an.map(function(a){\n    return '<div class=\"att ' + a.status + '\"><div class=\"top\"><span>' + ICON[a.status] + ' ' + esc(a.id) + '</span><span class=\"cnt\">виїздів ' + a.visitsFmt + '</span></div><div class=\"why\">Контракт ' + a.contractFmt + ' (' + a.priceFmt + ' за виїзд)<br>Акти ' + a.actsFmt + ' · надійшло ' + a.receivedFmt + ' · собівартість ' + a.costFmt + '<br>Рентабельність: план ' + a.rentPlanFmt + ' → прогноз ' + a.rentForecastFmt + ' · CPI ' + a.cpiFmt + (a.signals.length ? '<br>' + a.signals.map(esc).join('; ') : '') + '</div></div>';\n  }).join('') : '';\n";
html = html.replace(A, A.slice(0, -1) + " + anHtml;");
html = html.replace(B, AN_BLOCK + B);
return [{ json: Object.assign({}, out, { html: html }) }];

// Єдина форма звіту ПМа (WEEKLY_REPORT_FORM §2): ті самі пп. 1–12, підписи й формати, що в Weekly Render. LLM звіт не пише — лише ask.
// Показники 1,2,3 (+7,8) читає з archi_report_today (єдине обчислення в SQL); тут тільки форматування.
const P = $('WR: Parse Agent Output').first().json;
const A = (($('WR: Build WR Prompt').first().json || {}).auto || {}).stages || {};
const V = ($input.first() && $input.first().json && $input.first().json.project_id) ? $input.first().json : {};
const isFinal = P.tag === 'FINAL_REPORT';
const NL = String.fromCharCode(10);
const STG = ['МБР','ЕП','П','Р'];
const NUM_STG = ['ЕП','П','Р'];
const NUM_AT = { 'ЕП': 4, 'П': 5, 'Р': 6 };

function esc(s){ return String(s == null ? '' : s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;'); }
function num(v){ if (v === null || v === undefined || v === '') return null; const n = Number(v); return isNaN(n) ? null : n; }
function r1(n){ return Math.round(n * 10) / 10; }
function pct(v){ const n = num(v); return n === null ? '—' : r1(n) + '%'; }
function hrs(v){ const n = num(v); return n === null ? '—' : r1(n) + 'г'; }
function ratio(v){ const n = num(v); return n === null ? '—' : n.toFixed(2); }
function day(v){ if (!v) return '—'; const d = new Date(v); if (isNaN(d)) return String(v); return d.toLocaleDateString('uk-UA', { timeZone: 'Europe/Kyiv', day: '2-digit', month: '2-digit', year: 'numeric' }); }
function tenth(v){ const n = num(v); return n === null ? '—' : n + '/10'; }
const WAIT = '⏳ після «Фінал»';
const line = function(label, val){ return '<b>' + label + ':</b> ' + val; };

const na = Array.isArray(P.no_answer) ? P.no_answer : [];
const ready = P.stage_readiness || {};
const etcF = P.etc_forecast_stage || {};
const dlF = P.deadline_forecast_stage || {};

const out = [];
out.push('📋 <b>Звіт ПМ · ' + esc(P.project_id) + '</b>');
out.push('🗓 Тиждень з ' + day($now.startOf('week').toISO()));
out.push(isFinal ? '✅ Фінал' : '📄 Чернетка');
out.push('');

// 1. Рентабельність (F-15)
out.push(line('1. Рентабельність', pct(V.rent_plan_pct) + ' → ' + (!isFinal ? WAIT : (num(V.rent_forecast_pct) === null ? '🔴 відсутній' : pct(V.rent_forecast_pct)))));
// 2. ETC, год: Δ = ETC_прогноз − ETC_факт і колір (SQL: archi_vac_signal, S-04); підрядки — ETC_план / ETC_факт / ETC_прогноз (F-23, F-06)
const etcTotal = isFinal ? num(V.etc_forecast_hours) : num(P.etc_total_forecast);
const etcTotalTxt = etcTotal !== null ? hrs(etcTotal) : (P.etc_missing && P.etc_missing.length ? '— (ПМ не дав ETC по ' + P.etc_missing.join(', ') + ')' : '—');
const gapSig = { green: '🟢', yellow: '🟡', red: '🔴' };
const gapN = num(V.etc_gap_hours);
const gapTxt = !isFinal ? WAIT : (gapN === null ? '—' : 'Δ ' + (gapN > 0 ? '+' : '') + r1(gapN) + 'г ' + (gapSig[V.etc_gap_signal] || ''));
out.push(line('2. ETC, год', gapTxt));
out.push('   • ETC_план ' + hrs(V.etc_plan_hours));
out.push('   • ETC_факт ' + hrs(V.etc_fact_hours));
out.push('   • ETC_прогноз ' + etcTotalTxt);
// 3. Готовність (EVM, E-01…E-05): розбіжність Готовність ПМа − за прогнозом (п.п.) і ланцюжок; у чернетці — лише «Витрачено», решта після «Фінал»
const gapSigE = { green: '🟢', yellow: '🟡', red: '🔴' };
const rgN = num(V.ready_gap_pp);
const rgTxt = !isFinal ? WAIT : (rgN === null ? '—' : 'Δ ' + (rgN > 0 ? '+' : '') + r1(rgN) + ' п.п. ' + (gapSigE[V.ready_gap_signal] || ''));
out.push(line('3. Готовність · узгодженість', rgTxt));
out.push('   • Витрачено часу ' + pct(V.spent_pct));
out.push('   • Готовність ПМа ' + (!isFinal ? WAIT : pct(V.ready_pm_pct)));
out.push('   • За прогнозом ' + (!isFinal ? WAIT : pct(V.ready_fc_pct)));
out.push('   • Ефективність годин 1.00 → ' + (!isFinal ? WAIT : (num(V.eff_hours_idx) === null ? '—' : ratio(V.eff_hours_idx) + ' ' + (gapSigE[V.eff_signal] || ''))));
out.push('   • Ефективність виконання 1.00 → ' + (!isFinal ? WAIT : (num(V.exec_idx) === null ? '—' : ratio(V.exec_idx) + ' ' + (gapSigE[V.exec_signal] || ''))));

// 4–6. Стадії ЕП / П / Р (F-05) + підпункти ETC і дедлайн; МБР — довідково
function stageText(s){
  const a = A[s] || {};
  if (a.absent) return '— (немає в договорі)';
  if (ready[s] === undefined) return na.indexOf('готовність:' + s) >= 0 ? '❓ відповіді нема' : '— (немає даних)';
  return '100% → ' + ready[s] + '%' + (ready[s] >= 100 ? ' 🟢' : '');
}
function stageSubs(s){
  const a = A[s] || {};
  if (a.absent || ready[s] === undefined || ready[s] >= 100) return [];
  const f = etcF[s];
  const dl = dlF[s];
  return [
    '   • ETC_Стадія ' + s + ': план ' + hrs(a.etcPlan) + ' / факт ' + hrs(a.etcFact) + ' / прогноз ' + (f === undefined ? (na.indexOf('ETC:' + s) >= 0 ? '❓' : '—') : hrs(f)),
    '   • Дедлайн ' + s + ': план ' + day(a.deadlinePlanDate) + ' / прогноз ' + (dl ? day(dl) : (na.indexOf('дата:' + s) >= 0 ? '❓' : '—'))
  ];
}
const mbr = (A['МБР'] || {});
out.push('   МБР (довідково): ' + (mbr.absent ? '— (немає в договорі)' : (ready['МБР'] === undefined ? (na.indexOf('готовність:МБР') >= 0 ? '❓ відповіді нема' : '— (немає даних)') : ready['МБР'] + '%' + (ready['МБР'] >= 100 ? ' 🟢' : ''))));
NUM_STG.forEach(function (s) {
  out.push(line(NUM_AT[s] + '. Стадія ' + s, stageText(s)));
  stageSubs(s).forEach(function (l) { out.push(l); });
});

// 7. Акт (F-18): найближча дата · ймовірність; підпункти — по стадіях з Кошторису/Money_Log
out.push(line('7. Акт', day(V.act_date) + ' · ' + tenth(P.act_probability)));
out.push('   • Акти ÷ план на дату 1.00 → ' + (num(V.acts_plan_idx) === null ? '—' : ratio(V.acts_plan_idx) + ' ' + (gapSigE[V.acts_plan_signal] || '') + ' (' + V.acts_done + ' з ' + V.acts_due + ')'));
out.push('   • Виставлено ÷ освоєне (WIP) 1.00 → ' + (!isFinal ? WAIT : ratio(V.acts_to_ev)));
out.push('   • Оплата ÷ акти (&gt;1 — аванс) 1.00 → ' + ratio(V.paid_to_acts) + ' ' + (gapSigE[V.paid_to_acts_signal] || ''));
STG.forEach(function (s) {
  const a = A[s] || {};
  if (a.absent) return;
  out.push('   • ' + s + ': ' + (a.actSigned ? '✅ (підписаний)' : day(a.actPlanDate) + ' / ' + tenth(a.deadlineProb)));
});
// 8. Документація (F-19, F-20): дата · оцінка ПМ
out.push(line('8. Документація', day(V.doc_date) + ' · ' + (P.doc_probability === null || P.doc_probability === undefined ? (na.indexOf('документація') >= 0 ? '❓' : '—') : tenth(P.doc_probability))));
out.push('');

function textBlock(title, body, empty){
  out.push('<b>' + title + '</b>');
  const t = String(body == null ? '' : body).trim();
  out.push(t ? esc(t) : empty);
  out.push('');
}
// 9. Проблеми: блокер першим пунктом
const bl = P.blocker;
const blLine = (bl && bl.types && bl.types.length) ? '⛔ Блокер' + (bl.since ? ' з ' + day(bl.since) : '') + ': ' + esc(bl.types.join(', ')) + (bl.need ? ' — ' + esc(bl.need) : '') : null;
out.push('<b>9. Проблеми</b>');
if (blLine) out.push(blLine);
const pr = String(P.problems_text || '').trim();
if (pr) out.push(esc(pr));
if (!blLine && !pr) out.push('(без зауважень)');
out.push('');
// 10. Допомога
textBlock('10. Допомога', P.help_text, '(не потрібно)');
// 11. План на тиждень: перенесені пункти (🔴, лічильник) + нові — у тому ж порядку й нумерації, як їх збереже код; нижче — виконання минулого плану (PX-01)
out.push('<b>11. План на тиждень</b>');
const nextItems = Array.isArray(P.plan_next_items) ? P.plan_next_items : [];
if (nextItems.length) {
  nextItems.forEach(function (it, idx) {
    const cc = Number(it.carry_count) || 0;
    out.push((cc > 0 ? '🔴 ' : '') + (idx + 1) + '. ' + esc(it.text) + (cc > 0 ? ' (перенесено ×' + cc + ')' : ''));
  });
} else {
  out.push(na.indexOf('план') >= 0 ? '❓ відповіді нема' : '(дані ще не надано)');
}
const prevSt = Array.isArray(P.plan_prev) ? P.plan_prev : [];
if (prevSt.length) {
  out.push('');
  const cnt = function (s) { return prevSt.filter(function (p) { return p.st === s; }).length; };
  const sigEmoji = { green: '🟢', yellow: '🟡', red: '🔴' };
  const confirmed = isFinal && num(V.pe_total) !== null && num(V.pe_pending) === 0 && num(V.pe_pct) !== null;
  out.push(confirmed
    ? '<b>Виконання минулого плану:</b> ' + V.pe_done + ' з ' + V.pe_total + ' · ' + V.pe_pct + '% ' + (sigEmoji[V.pe_signal] || '')
    : '<b>Виконання минулого плану:</b> ✅ ' + cnt('done') + ' · ❌ ' + cnt('not_done') + ' · ❓ ' + cnt('no_answer') + ' · ⏳ ' + cnt('pending') + (isFinal ? '' : ' (відсоток — після «Фінал»)'));
  prevSt.forEach(function (p) { out.push((p.st === 'done' ? '✅' : (p.st === 'not_done' ? '❌' : (p.st === 'no_answer' ? '❓' : '⏳'))) + ' ' + p.n + '. ' + esc(p.text) + (p.carry_count > 0 ? ' (перенесено ×' + p.carry_count + ')' : '')); });
}
out.push('');
// 12. Коментар ПМ
textBlock('12. Коментар ПМ', P.pm_comment_text, '(дані ще не надано)');

const pre = (P.pre_blocks || []).join(NL + NL);
const post = (P.post_blocks || []).join(NL + NL);
const askTxt = String(P.ask || '').trim();
let message = 'Станом на ' + day(V.data_updated_at) + NL + NL + (pre ? pre + NL + NL : '') + out.join(NL).replace(/\n+$/, '') + (post ? NL + NL + post : '') + (askTxt ? NL + NL + '🎯 <b>Що потрібно від вас:</b>' + NL + askTxt : '');
return [{ json: { tag: P.tag, message: message } }];
